/**
 * Cloudflare Worker entry point — auto-generated by vinext deploy.
 * Edit freely or delete to regenerate on next deploy.
 *
 * For apps without image optimization, you can use vinext/server/app-router-entry
 * directly in wrangler.jsonc: "main": "vinext/server/app-router-entry"
 */
import {
  handleImageOptimization,
  isImageOptimizationPath,
  DEFAULT_DEVICE_SIZES,
  DEFAULT_IMAGE_SIZES,
} from 'vinext/server/image-optimization';
import handler from 'vinext/server/app-router-entry';
import { runWithDb } from '../lib/db';
import { getEmail, type SendEmail } from '../lib/email';
import { getStorage } from '../lib/r2';
import { getRelay } from '../lib/relay/crosspost-client';
import { setInternalAuthToken } from '../lib/server/internal-auth';
import { hostnameFor, resolveSurface } from '../lib/panaverse/surfaces';
import { assertPanaverseConfigured } from '../lib/panaverse/boot';
import { runExpiryPurge } from '../lib/jobs/purge-expired';
import { beginJobRun, completeJobRun, PURGE_JOB } from '../lib/jobs/ledger';
import { recordSyntheticRun } from '../lib/jobs/synthetic-check';
import { getDmStream } from '../lib/dm-stream';
import { resolveUserIdFromHeaders } from '../auth';
import { getActiveProfileWithActor } from '../lib/server/active-profile';
import { PATHNAME_HEADER, SEARCH_HEADER } from '../lib/panaverse/chrome';

// Re-export Durable Object classes so wrangler can discover them
export { SignalingRoom } from './signaling-room';
export { DmStream } from './dm-stream';

interface Env {
  ASSETS: Fetcher;
  HYPERDRIVE: { connectionString: string };
  POSTGRES_URL?: string; // local dev only: wrangler secret binding from .env.local
  R2_BUCKET?: {
    put(
      key: string,
      value:
        ArrayBuffer | ArrayBufferView | ReadableStream | string | null | Blob,
      options?: { httpMetadata?: { contentType?: string } }
    ): Promise<unknown>;
    delete(keys: string | string[]): Promise<void>;
    get(
      key: string,
      options?: { range?: { offset: number; length?: number } }
    ): Promise<{ arrayBuffer(): Promise<ArrayBuffer> } | null>;
  };
  // Optional: the "images" binding in wrangler.jsonc is currently commented
  // out, so this is undefined at runtime. Typed optional so the call site is
  // forced to guard rather than throwing on every image request.
  IMAGES?: {
    input(stream: ReadableStream): {
      transform(options: Record<string, unknown>): {
        output(options: {
          format: string;
          quality: number;
        }): Promise<{ response(): Response }>;
      };
    };
  };
  EMAIL?: SendEmail;
  SIGNALING_ROOM: DurableObjectNamespace;
  DM_STREAM: DurableObjectNamespace;
  // Service binding to the panamia-nosflare relay Worker (Nostr crosspost +
  // NIP-29 relay ops). Optional: crosspost is best-effort and no-ops if unbound.
  RELAY?: Fetcher;
  CROSSPOST_AUTH_TOKEN?: string;
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    /* Configuration that must hold before this deployment serves anybody.
     *
     * Runs here rather than at module scope because Worker bindings are not
     * populated until an invocation exists — top-level code would read an
     * empty environment and pass regardless of how it is configured. Memoised
     * inside, so this is one string comparison per request after the first.
     *
     * Throwing takes the deployment down on its first public request. That is
     * the intent: the failure it guards against is silent and permanent (see
     * lib/panaverse/boot.ts), and an outage is recoverable in a way that
     * orphaned fediverse identities are not. */
    assertPanaverseConfigured(request.headers.get('host'));

    const requestUrl = new URL(request.url);
    if (requestUrl.hostname === 'shop.panamia.club') {
      const destination =
        requestUrl.pathname === '/cart' ? '/shop/cart' : '/shop';
      return Response.redirect(
        `https://panamia.club${destination}${requestUrl.search}`,
        308
      );
    }

    // Prime the R2/email/relay caches with CF bindings before any application
    // code runs. These hold plain binding objects, which are safe to reuse.
    getEmail(env);
    getStorage(env);
    getRelay(env);
    getDmStream(env);
    // Shared secret for app/api/internal/* — the bearer fallback for a caller
    // that reaches those routes over HTTP rather than the Service Binding.
    setInternalAuthToken(env);

    // The DB client is the exception: postgres.js sockets belong to the request
    // that opened them, so it is scoped to this request rather than shared.
    // Everything downstream must run inside this callback for `db` to resolve.
    return runWithDb(env, async () => {
      const url = requestUrl;

      // Live DM delivery — route /ws/dm to the signed-in member's own mailbox.
      //
      // Deliberately unlike the /ws/signaling/ branch below it. That one takes
      // a room id from the URL and routes straight through, leaving the DO to
      // trust whatever identity the client claims in its join message. For a
      // mentoring proof-of-concept behind unguessable room ids that is
      // survivable; for messaging it would mean anyone could open a socket and
      // read anyone's mail.
      //
      // So the mailbox is never named by the client. The session is resolved
      // here, the actor is derived from it server-side, and *that* is what
      // idFromName() receives. There is no request parameter to tamper with:
      // the only mailbox reachable from this endpoint is the caller's own.
      //
      // This must stay inside runWithDb — resolving the session and the actor
      // are both database reads.
      if (url.pathname === '/ws/dm') {
        if (request.headers.get('Upgrade') !== 'websocket') {
          return new Response('Expected WebSocket upgrade', { status: 426 });
        }

        // Cookies are sent automatically on a same-origin upgrade, and a native
        // client sets the same header by hand. See resolveUserIdFromHeaders.
        const userId = await resolveUserIdFromHeaders(request.headers);
        if (!userId) {
          return new Response('Unauthorized', { status: 401 });
        }

        const profile = await getActiveProfileWithActor(userId);
        if (!profile?.socialActor) {
          // Signed in but onboarding is incomplete, so there is no mailbox to
          // open. 403 rather than 401: retrying with credentials will not help.
          return new Response('No social actor for this account', {
            status: 403,
          });
        }

        const id = env.DM_STREAM.idFromName(profile.socialActor.id);
        return env.DM_STREAM.get(id).fetch(request);
      }

      // WebSocket signaling for WebRTC — route /ws/signaling/:roomId to Durable Object
      if (url.pathname.startsWith('/ws/signaling/')) {
        const roomId = url.pathname.split('/')[3];
        if (!roomId) {
          return new Response('Room ID required', { status: 400 });
        }
        const id = env.SIGNALING_ROOM.idFromName(roomId);
        const stub = env.SIGNALING_ROOM.get(id);
        return stub.fetch(request);
      }

      // Image optimization via Cloudflare Images binding.
      // The parseImageParams validation inside handleImageOptimization
      // normalizes backslashes and validates the origin hasn't changed.
      // Match both /_next/image (emitted by the next/image shim) and the
      // /_vinext/image alias — matching only one path 404s the other.
      if (isImageOptimizationPath(url.pathname)) {
        const allowedWidths = [...DEFAULT_DEVICE_SIZES, ...DEFAULT_IMAGE_SIZES];
        const images = env.IMAGES;
        return handleImageOptimization(
          request,
          {
            fetchAsset: (path) =>
              env.ASSETS.fetch(new Request(new URL(path, request.url))),
            // Omitted when the binding is absent: handleImageOptimization then
            // serves the source image through its passthrough path directly,
            // instead of throwing once per request and logging the failure.
            transformImage: images
              ? async (body, { width, format, quality }) => {
                  const result = await images
                    .input(body)
                    .transform(width > 0 ? { width } : {})
                    .output({ format, quality });
                  return result.response();
                }
              : undefined,
          },
          allowedWidths
        );
      }

      // Panaverse host routing: a surface hostname serves that surface's front
      // door at its own root, so social.pana.social/ is the feed and the URL
      // says so. The page is chosen from the hostname in app/page.tsx — one
      // route tree, two front doors — so the canonical host needs no redirect
      // here. Every other route stays reachable from every hostname, so /api,
      // /.well-known, and shared pages behave identically no matter which
      // surface a request arrives on.
      //
      // Branching in the route rather than rewriting here is forced: vinext
      // has no middleware-rewrite signalling, so serving /s under the URL "/"
      // would leave the client router fetching RSC payloads for the wrong
      // path. A route group cannot express it either — app/(social)/page.tsx
      // still resolves to "/" and collides with app/page.tsx, because both
      // surfaces share one route tree and only the hostname tells them apart.
      //
      // What does still redirect is an alias host. Visitors who type the
      // fediverse identity domain get handed to the real UI host; that domain
      // stays a thin identity endpoint serving WebFinger and actor JSON, which
      // pass through untouched above. *.localhost counts as canonical so dev
      // mirrors the production split instead of being bounced to the live site.
      const surface = resolveSurface(url.hostname);
      if (
        url.pathname === '/' &&
        surface.rootPath !== '/' &&
        !url.hostname.endsWith('.localhost') &&
        url.hostname !== hostnameFor(surface)
      ) {
        const target = new URL(url.toString());
        target.protocol = 'https:';
        target.hostname = hostnameFor(surface);
        target.port = '';
        return Response.redirect(target.toString(), 307);
      }

      // Delegate everything else to vinext, telling the server renderer which
      // path it is about to serve. The runtime hands it Host but not the path,
      // so without this the root layout cannot tell a doorway like /signin from
      // an ordinary page (see lib/panaverse/chrome.ts).
      //
      // `set`, never `append`: clients can send this header too, and a spoofed
      // value would let anyone strip the chrome off any page.
      const routed = new Request(request);
      routed.headers.set(PATHNAME_HEADER, url.pathname);
      routed.headers.set(SEARCH_HEADER, url.search);
      return handler.fetch(routed);
    });
  },

  /**
   * Hourly maintenance. Expiry across this app is a read filter, so rows
   * whose `expiresAt` has passed are invisible but still stored -- along with
   * their R2 media, which nothing else ever reclaims. See lib/jobs/purge-expired.ts.
   *
   * Bindings are primed here exactly as in fetch(): a scheduled invocation is
   * a separate entry point and gets none of that setup for free. runWithDb
   * matters most -- postgres.js sockets are scoped to the invocation that
   * opened them, so the job has to run inside it.
   */
  async scheduled(event: { cron: string }, env: Env): Promise<void> {
    getStorage(env);

    // Awaited rather than handed to ctx.waitUntil, and errors are rethrown.
    // Both matter for observability: waitUntil lets the handler return before
    // the work finishes, so Cloudflare records the run as a success in a few
    // milliseconds regardless of outcome. Awaiting makes the dashboard's
    // duration and failure columns mean something.
    await runWithDb(env, async () => {
      // Uptime probes first, and they cannot throw -- see the note in
      // lib/jobs/synthetic-check.ts. Ahead of the purge rather than after it
      // because the purge rethrows on failure: running second would mean a
      // broken sweep also blinds the dashboard that reports on it, which is
      // exactly when somebody is looking.
      await recordSyntheticRun(event.cron);

      // Recorded in job_runs as well as logged. The console line is kept
      // because it is the only thing visible during a live tail; the ledger
      // row is the only thing visible an hour later. See lib/jobs/ledger.ts
      // for why nothing in this block can be broken by the ledger failing.
      const run = await beginJobRun(PURGE_JOB, event.cron);

      try {
        const report = await runExpiryPurge();
        console.log('[purge]', event.cron, JSON.stringify(report));

        // Logged individually rather than left inside the report blob. A
        // deferred story means an R2 object outlived the row that pointed at
        // it; it retries tomorrow, but a run of them is a bucket problem and
        // should be greppable.
        for (const error of report.errors) {
          console.error('[purge]', error);
        }

        await completeJobRun(run, {
          ok: true,
          report,
          errorCount: report.errors.length,
        });
      } catch (error) {
        // Record the failure, then rethrow unchanged. The ledger is additive:
        // Cloudflare's own failure column is still the thing that pages
        // somebody, and swallowing here to keep the row tidy would trade a
        // real alert for a dashboard entry.
        const message = error instanceof Error ? error.message : String(error);
        await completeJobRun(run, {
          ok: false,
          report: { error: message },
          errorCount: 1,
        });
        throw error;
      }
    });
  },
};
